public interface VoucherAttachmentService {
  VoucherAttachmentDTO uploadAttachment(UUID voucherId, MultipartFile file) throws IOException;
  List<VoucherAttachmentDTO> listAttachments(UUID voucherId);
  String generateSignedUrl(UUID voucherId, UUID attachmentId) throws IOException;
  void deleteAttachment(UUID voucherId, UUID attachmentId, String reason);
  void validateFile(MultipartFile file) throws ValidationException;
}

public interface VirusScanService {
  ScanResult scanFile(MultipartFile file) throws ScanException;
}

public class ScanResult {
  boolean passed;
  String errorMessage;
}

public class VoucherAttachmentDTO {
  UUID id;
  UUID voucherId;
  String fileName;
  String mimeType;
  Long fileSize;
  LocalDateTime uploadedAt;
  UUID uploadedBy;
  String uploadedByName;
}

@Entity
@Table(name = "voucher_attachments")
public class VoucherAttachment implements CompanyScopedEntity {
  @Id
  @GeneratedValue(strategy = GenerationType.UUID)
  private UUID id;

  @ManyToOne
  @JoinColumn(name = "voucher_id", nullable = false)
  private Voucher voucher;

  @Column(nullable = false)
  private String fileName;

  @Column(nullable = false)
  private String storagePath;

  @Column(nullable = false)
  private String mimeType;

  @Column(nullable = false)
  private Long fileSize;

  @Column(nullable = false)
  private UUID companyId;

  private LocalDateTime uploadedAt;
  private UUID uploadedBy;
}
